using System.Collections;
using System.Linq;
using UnityEngine;
using UnityEngine.UI;
class OfficeSession : MonoBehaviour {
 internal static void Ensure(){var button=Resources.FindObjectsOfTypeAll<Button>().FirstOrDefault(b=>FloorAdmin.PathOf(b.transform)=="OverlayGUI/Gameplay/ExitButton/ExitButton");if(button!=null&&button.GetComponent<OfficeSession>()==null)button.gameObject.AddComponent<OfficeSession>().Bind(button);}
 void Bind(Button button){var original=button.onClick;button.onClick=new Button.ButtonClickedEvent();button.onClick.AddListener(()=>{bool office=UnityEngine.SceneManagement.SceneManager.GetSceneByName("BossRoom").isLoaded;if(office){if(AdminPaperDesk.Current!=null)AdminPaperDesk.Current.ForceClose();foreach(var shot in FindObjectsOfType<AdminSceneShot>())shot.Close();OfficeSeating.End();}original.Invoke();if(office)FloorAdmin.Instance.StartCoroutine(Release());});}
 IEnumerator Release(){yield return new WaitForSecondsRealtime(2f);var player=PlayerActionsSystem.Instance;if(player!=null&&!InkController.AnyInProgress){if(player.IsBusy)player.FinishAllActions();var desk=Resources.FindObjectsOfTypeAll<Transform>().FirstOrDefault(t=>t.gameObject.scene.name=="BossRoom"&&FloorAdmin.PathOf(t)=="Active/FurnitureActions/WorkplaceBoss");if(desk!=null){foreach(var camera in desk.GetComponentsInChildren<Cinemachine.CinemachineVirtualCameraBase>(true))camera.gameObject.SetActive(false);var terminal=desk.Find("Terminal/TerminalFreeTime");if(terminal!=null)terminal.gameObject.SetActive(false);foreach(var collider in desk.GetComponents<Collider>())collider.enabled=true;}OfficeSeating.End();HarmonyLib.AccessTools.Field(typeof(PlayerNavigation),"m_Lock").SetValue(null,0);if(Camera.main!=null){var focus=Camera.main.GetComponent<UnityStandardAssets.ImageEffects.DepthOfField>();if(focus!=null)focus.focalTransform=player.transform;}if(SceneController.Instance!=null)SceneController.Instance.Fade(0,.25f);FloorAdmin.Log("DESK exit navigation and fade released busy="+player.IsBusy);}}
}
